	{3, 7, 6, 2},
	{0, 4, 5, 1},
	{6, 7, 5, 4},
	{3, 2, 0, 1},
	{7, 3, 1, 5},
	{2, 6, 4, 0},
};

// Standard index set to make a quad on 4 vertices
static constexpr u16 quad_indices_02[] = {0, 1, 2, 2, 3, 0};
static constexpr u16 quad_indices_13[] = {0, 1, 3, 3, 1, 2};
static const auto &quad_indices = quad_indices_02;

